using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // EF Core 9 breaking change: Migrate() now manages its own transactions
    // and ExecutionStrategy. Wrapping it in a user transaction throws.
    // Fix: call MigrateAsync() directly without an outer transaction.
    async Task ApplyMigrationsAsync(AppDbContext db, CancellationToken ct = default)
    {
        await db.Database.MigrateAsync(ct);
    }
}

