using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

/// <summary>
/// Demonstrates EF Core 9 Cosmos DB breaking-change fixes for a container
/// with existing documents that used the old "Discriminator" property.
/// </summary>
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "AppDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Session>(b =>
        {
            b.ToContainer("Sessions");

            // EF Core 9 breaking change #1: discriminator property renamed
            // from "Discriminator" to "$type". Existing documents use the old name.
            b.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change #2: id property no longer contains the
            // discriminator value. Existing documents have "Session|<key>" format.
            // Preserve the old format so point-reads still find existing docs.
            b.HasRootDiscriminatorInJsonId(true);
        });
    }

    // EF Core 9 breaking change #3: Cosmos provider no longer supports
    // synchronous I/O. All queries and SaveChanges must use async equivalents.
    //
    // BEFORE (throws in EF Core 9):
    //   var list = db.Sessions.ToList();
    //   db.SaveChanges();
    //
    // AFTER:
    async Task<List<Session>> GetSessionsAsync(CancellationToken ct = default)
    {
        return await Sessions.ToListAsync(ct);
    }

    async Task SaveAsync(CancellationToken ct = default)
    {
        await SaveChangesAsync(ct);
    }
}

class Session
{
    public string Id { get; set; } = "";
    public string Name { get; set; } = "";
}

